INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V00107', 'ᨠ᩠ᩃ᩠ᩋᨦᨸᩪ᩵ᨩᩣ', 'ก๋องปู่จา', 'กลองปู่ชา', 'น.กลองบูชา - กลองสองหน้าขนาดใหญ่ รูปทรงกระบอก เส้นผ่าศูนย์กลางประมาณ ๑ เมตร ใช้ตีเป็นพุทธบูชาในวันโกนหรือวันพระ โดยมีกลองขนาดเล็ก เรียก ก๋องต๘+อบ หรือ ก๋องตุ๋บ อีกสามใบให้จังหวะในการตี', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨠ᩠ᩃ᩠ᩋᨦᨸᩪ᩵ᨩᩣ', `reading`='ก๋องปู่จา', `meaning`='น.กลองบูชา - กลองสองหน้าขนาดใหญ่ รูปทรงกระบอก เส้นผ่าศูนย์กลางประมาณ ๑ เมตร ใช้ตีเป็นพุทธบูชาในวันโกนหรือวันพระ โดยมีกลองขนาดเล็ก เรียก ก๋องต๘+อบ หรือ ก๋องตุ๋บ อีกสามใบให้จังหวะในการตี', `category_vocab_id`='CV0017';
