INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V00329', 'ᨠᩣ', '[ก๋า]', 'กา', '1. น. อีกา 2. น. ตรา เครื่องหมาย 3. น. ภาชนะใช้ต้มน้ำ 4. น. พัดขนาดใหญ่ที่ใช้พัดข้าวลีบออกจากกองข้าวในช่วงการนวดข้าว 5. น. เรียกวัวที่มีสีเดียวตลอดตัวแต่มีสีขาวที่หน้าผาก หรือวัวสีดำปลอด ว่า งัวกา ถ้าสีขาวปลอดเรียก งัวไหม 6. น. ในตำนานพื้นเมืองเชียงใหม่ คำว่า กา หมายถึง กาลกิณีเมือง 7. ก. หมายไว้ ทำเครื่องหมายไว้ คำลงท้ายแสดงคำถามหรือแสดงความไม่พอใจ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨠᩣ', `reading`='[ก๋า]', `meaning`='1. น. อีกา 2. น. ตรา เครื่องหมาย 3. น. ภาชนะใช้ต้มน้ำ 4. น. พัดขนาดใหญ่ที่ใช้พัดข้าวลีบออกจากกองข้าวในช่วงการนวดข้าว 5. น. เรียกวัวที่มีสีเดียวตลอดตัวแต่มีสีขาวที่หน้าผาก หรือวัวสีดำปลอด ว่า งัวกา ถ้าสีขาวปลอดเรียก งัวไหม 6. น. ในตำนานพื้นเมืองเชียงใหม่ คำว่า กา หมายถึง กาลกิณีเมือง 7. ก. หมายไว้ ทำเครื่องหมายไว้ คำลงท้ายแสดงคำถามหรือแสดงความไม่พอใจ', `category_vocab_id`='CV0017';
