INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V00635', 'ᨡ᩠ᩅᩣ᩠ᨠᨪᩩ᩠ᨿ', '[ขวาก - ซุย]', 'ขวากซุย', 'น. วิชารักษากระดูกหัก โดยใช้เวทมนตร์ ตัวเฝือกที่ใช้ดามกระดูกแขนขาหักทำด้วยไม้ไผ่หลาบบางๆ ถักยึดด้วยเส้นด้ายหรือเชือก ก่อนใส่เฝือก (ขวากซุย) ทาแผลด้วยน้ำมันมนต์พร้อมเป่าคาถา ระยะเวลาการรักษากระดูกหักนี้จะเร็วกว่าการแพทย์แผนปัจจุบัน', 'CV0011') ON DUPLICATE KEY UPDATE `lanna_word`='ᨡ᩠ᩅᩣ᩠ᨠᨪᩩ᩠ᨿ', `reading`='[ขวาก - ซุย]', `meaning`='น. วิชารักษากระดูกหัก โดยใช้เวทมนตร์ ตัวเฝือกที่ใช้ดามกระดูกแขนขาหักทำด้วยไม้ไผ่หลาบบางๆ ถักยึดด้วยเส้นด้ายหรือเชือก ก่อนใส่เฝือก (ขวากซุย) ทาแผลด้วยน้ำมันมนต์พร้อมเป่าคาถา ระยะเวลาการรักษากระดูกหักนี้จะเร็วกว่าการแพทย์แผนปัจจุบัน', `category_vocab_id`='CV0011';
