INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V00762', 'ᨡᩢ᩠ᨶ', '[ขัน]', 'ขัน', '1. น. พาน 2. น. อัตราลงโทษแบบโบราณ คือ ขันค่าคอ - โทษประหารชีวิต ขันไหม - โทษปรับไหม ขันแปลง - โทษซ่อมแซมหรือสร้างสิ่งชำรุดไปให้เหมือนเดิม ขันสมมา - โทษเพียงให้ผู้กระทำผิดขอขมาแก่ผู้เสียหาย 3. ก. ทำให้ตึง ทำให้แน่น ประกันหรือรับรองว่าจะรับผิดชอบในเรื่องที่จะเกิดขึ้น อาสา เสนอตัวเข้ารับทำโดยเต็มใจ ขันอย่างนกหรือไก่ พนัน', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨡᩢ᩠ᨶ', `reading`='[ขัน]', `meaning`='1. น. พาน 2. น. อัตราลงโทษแบบโบราณ คือ ขันค่าคอ - โทษประหารชีวิต ขันไหม - โทษปรับไหม ขันแปลง - โทษซ่อมแซมหรือสร้างสิ่งชำรุดไปให้เหมือนเดิม ขันสมมา - โทษเพียงให้ผู้กระทำผิดขอขมาแก่ผู้เสียหาย 3. ก. ทำให้ตึง ทำให้แน่น ประกันหรือรับรองว่าจะรับผิดชอบในเรื่องที่จะเกิดขึ้น อาสา เสนอตัวเข้ารับทำโดยเต็มใจ ขันอย่างนกหรือไก่ พนัน', `category_vocab_id`='CV0017';
