INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02261', 'ᨯ', '[ดะ]', 'ด', 'พยัญชนะตัวที่ 16 /d/ นับเป็นอักษรกลาง อ่านว่า ดะ ใช้เป็นพยัญชนะต้นและตัวสะกดในมาตราแม่กด เมื่อเขียนศัพท์ภาษาบาลีตรงกับรูปอักษร ท ถ้าเขียนคำเขมรตรงกับรูป ฎ หากเป็นศัพท์ภาษาล้านนาแล้วใช้รูปอักษร ด', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨯ', `reading`='[ดะ]', `meaning`='พยัญชนะตัวที่ 16 /d/ นับเป็นอักษรกลาง อ่านว่า ดะ ใช้เป็นพยัญชนะต้นและตัวสะกดในมาตราแม่กด เมื่อเขียนศัพท์ภาษาบาลีตรงกับรูปอักษร ท ถ้าเขียนคำเขมรตรงกับรูป ฎ หากเป็นศัพท์ภาษาล้านนาแล้วใช้รูปอักษร ด', `category_vocab_id`='CV0017';
