INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02286', 'ᨯᩬᨠᩉᨾᩣᨠ', '[ดอก - หมาก]', 'ดอกหมาก', 'น. จั่นหมาก ดอกของต้นหมาก; เกลื้อนชนิดหนึ่งขึ้นตามตัวตามหลังเป็นผื่นขาว ๆ มักเรียกคู่กับเกลื้อนอีกชนิดหนึ่งว่า ขี้เสื้อนดอกหมาก ขี้มากดอกปอ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨯᩬᨠᩉᨾᩣᨠ', `reading`='[ดอก - หมาก]', `meaning`='น. จั่นหมาก ดอกของต้นหมาก; เกลื้อนชนิดหนึ่งขึ้นตามตัวตามหลังเป็นผื่นขาว ๆ มักเรียกคู่กับเกลื้อนอีกชนิดหนึ่งว่า ขี้เสื้อนดอกหมาก ขี้มากดอกปอ', `category_vocab_id`='CV0017';
