INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02397', 'ᨯᩥ᩶ᨾ', '[ดิ้ม]', 'ดิ้ม', 'ว. คำที่ใช้เติมหลังคำที่มีความหมายว่าสั้นหรือเล็ก เช่น เสื้อสั้นกั้มดิ้ม หมาหางกิดไต้คันนาดิ้ม ๆ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨯᩥ᩶ᨾ', `reading`='[ดิ้ม]', `meaning`='ว. คำที่ใช้เติมหลังคำที่มีความหมายว่าสั้นหรือเล็ก เช่น เสื้อสั้นกั้มดิ้ม หมาหางกิดไต้คันนาดิ้ม ๆ', `category_vocab_id`='CV0017';
