INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02478', 'ᨯ᩶ᩬ᩠ᨿ', '[ด้อย]', 'ด้อย', 'ก. เป็นด้อย; ว. อาการเคยชินในทางที่ไม่ดี เช่น กินกับเดิมหรือพูดโผงผางจนเคยตัว เรียกว่าเป็นด้อยปาก; ต่ำ เลว (ไทยใหญ่ หลอย เท่ากับ ด้อย แปลว่า กิน) กินจุบกินจิบ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨯ᩶ᩬ᩠ᨿ', `reading`='[ด้อย]', `meaning`='ก. เป็นด้อย; ว. อาการเคยชินในทางที่ไม่ดี เช่น กินกับเดิมหรือพูดโผงผางจนเคยตัว เรียกว่าเป็นด้อยปาก; ต่ำ เลว (ไทยใหญ่ หลอย เท่ากับ ด้อย แปลว่า กิน) กินจุบกินจิบ', `category_vocab_id`='CV0017';
