INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02945', 'ᨲᩫ᩶ᨶᨿ᩠ᩅᨾ', '[ต้น - ญวม]', 'ต้นยวม', 'น. ชื่อแม่น้ำหนึ่งในจังหวัดแม่ฮ่องสอน ชื่อเมืองหนึ่งปัจจุบันคืออำเภอแม่สะเรียง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨲᩫ᩶ᨶᨿ᩠ᩅᨾ', `reading`='[ต้น - ญวม]', `meaning`='น. ชื่อแม่น้ำหนึ่งในจังหวัดแม่ฮ่องสอน ชื่อเมืองหนึ่งปัจจุบันคืออำเภอแม่สะเรียง', `category_vocab_id`='CV0017';
