INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02948', 'ᨲᩫ᩶ᨶᩉ᩠ᨾᩣᨠ', '[ต้น - หมาก]', 'ต้นหมาก', 'น. ต้นหมาก หมากสุ่ม หมากเบง เครื่องสักการะมีโครงเป็นไม้หรือโลหะ ประดับด้วยหมากสุกรองด้วยใบตอง ในมะพร้าวประดิษฐ์', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨲᩫ᩶ᨶᩉ᩠ᨾᩣᨠ', `reading`='[ต้น - หมาก]', `meaning`='น. ต้นหมาก หมากสุ่ม หมากเบง เครื่องสักการะมีโครงเป็นไม้หรือโลหะ ประดับด้วยหมากสุกรองด้วยใบตอง ในมะพร้าวประดิษฐ์', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02949', 'ᨲᩫ᩶ᨶᩁᩢᨠ', '[ต้น - ฮัก]', 'ต้นฮัก', 'น. ต้นรัก ชื่อพรรณไม้ยืนต้นขนาดใหญ่หลายชนิด ยางเป็นพิษใช้ลงพื้นหรือทาสิ่งของต่าง ๆ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨲᩫ᩶ᨶᩁᩢᨠ', `reading`='[ต้น - ฮัก]', `meaning`='น. ต้นรัก ชื่อพรรณไม้ยืนต้นขนาดใหญ่หลายชนิด ยางเป็นพิษใช้ลงพื้นหรือทาสิ่งของต่าง ๆ', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02950', 'ᨲᩫ᩶ᨶᨦᩮᩥᨶ', '[ต้น - เงิน]', 'ต้นเงิน', 'น. เครื่องไทยทานที่มีโครงทำด้วยมัดฟางเป็นสามขาแล้วรวบเป็นลำเดียว สูงประมาณ 50 เซนติเมตร ประดับด้วยเงินธนบัตรคีบด้วยไม้ไผ่ผ่าซีก ผูกรัดด้วยเส้นด้าย และประดับด้วยดอกไม้ประดิษฐ์', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨲᩫ᩶ᨶᨦᩮᩥᨶ', `reading`='[ต้น - เงิน]', `meaning`='น. เครื่องไทยทานที่มีโครงทำด้วยมัดฟางเป็นสามขาแล้วรวบเป็นลำเดียว สูงประมาณ 50 เซนติเมตร ประดับด้วยเงินธนบัตรคีบด้วยไม้ไผ่ผ่าซีก ผูกรัดด้วยเส้นด้าย และประดับด้วยดอกไม้ประดิษฐ์', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V02951', 'ᨲᩫ᩶ᨶᨹᩮᩥ᩶ᨦ', '[ต้น - เผิ้ง]', 'ต้นเผิ้ง', 'น. ต้นผึ้ง เครื่องไทยทานมีโครงทำด้วยไม้ โลหะ หรือต้นกล้วย ประดับด้วยดอกไม้ทำจากขี้ผึ้งและเทียน มักใช้ในงานทอดกฐิน; ต้นไม้ที่ผึ้งทำรัง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨲᩫ᩶ᨶᨹᩮᩥ᩶ᨦ', `reading`='[ต้น - เผิ้ง]', `meaning`='น. ต้นผึ้ง เครื่องไทยทานมีโครงทำด้วยไม้ โลหะ หรือต้นกล้วย ประดับด้วยดอกไม้ทำจากขี้ผึ้งและเทียน มักใช้ในงานทอดกฐิน; ต้นไม้ที่ผึ้งทำรัง', `category_vocab_id`='CV0017';
