INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03064', 'ᨳ᩵ᩫ᩠ᩅᩮᨶ᩵ᩣ', '[ถั่ว-เน่า]', 'ถั่วเน่า', 'น. ถั่วเหลือง ถั่วเหลืองต้มเปื่อยหมักให้ขึ้นราเล็กน้อยแล้วตำให้ละเอียด จากนั้นทำเป็นแผ่นบางกลมกว้างประมาณ 3 นิ้ว ตากแดดให้แห้งเก็บไว้ปรุงอาหาร เรียกว่า ถั่วเน่าแช็บ; ถ้านำมาต่อด้วยใบตองแล้วนึ่งหรือย่างไว้ปรุงอาหาร เรียกว่า ถั่วเน่าห่อ; ปรกติถั่วเน่าแช็บเก็บได้นานกว่าถั่วเน่าห่อ เรียกชนิดนั้นหมัก', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨳ᩵ᩫ᩠ᩅᩮᨶ᩵ᩣ', `reading`='[ถั่ว-เน่า]', `meaning`='น. ถั่วเหลือง ถั่วเหลืองต้มเปื่อยหมักให้ขึ้นราเล็กน้อยแล้วตำให้ละเอียด จากนั้นทำเป็นแผ่นบางกลมกว้างประมาณ 3 นิ้ว ตากแดดให้แห้งเก็บไว้ปรุงอาหาร เรียกว่า ถั่วเน่าแช็บ; ถ้านำมาต่อด้วยใบตองแล้วนึ่งหรือย่างไว้ปรุงอาหาร เรียกว่า ถั่วเน่าห่อ; ปรกติถั่วเน่าแช็บเก็บได้นานกว่าถั่วเน่าห่อ เรียกชนิดนั้นหมัก', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03065', 'ᨳ᩵ᩫ᩠ᩅᩮᨶ᩵ᩣᩮᨾ᩠ᩋᩥᩡ', '[ถั่ว-เน่า-เมอะ]', 'ถั่วเน่าเมอะ', 'น. ถั่วเน่าชนิดที่เตรียมอย่างถั่วเน่าแช็บหรือถั่วเน่าห่อ แต่ในขณะที่ตำให้ละเอียดนั้นอาจปรุงรสให้จัดขึ้นแล้วนำมาต่อบั้งไฟหรือนึ่งกินเป็นอาหาร อาจเติมไข่ลงไปด้วยก็ได้; ปรกติในขบวนการเตรียมถั่วเน่าไว้ปรุงอาหารนั้น ชาวบ้านมักจะทำถั่วเน่าเมอะกินเสมอ (เมอะ = เข้ม)', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨳ᩵ᩫ᩠ᩅᩮᨶ᩵ᩣᩮᨾ᩠ᩋᩥᩡ', `reading`='[ถั่ว-เน่า-เมอะ]', `meaning`='น. ถั่วเน่าชนิดที่เตรียมอย่างถั่วเน่าแช็บหรือถั่วเน่าห่อ แต่ในขณะที่ตำให้ละเอียดนั้นอาจปรุงรสให้จัดขึ้นแล้วนำมาต่อบั้งไฟหรือนึ่งกินเป็นอาหาร อาจเติมไข่ลงไปด้วยก็ได้; ปรกติในขบวนการเตรียมถั่วเน่าไว้ปรุงอาหารนั้น ชาวบ้านมักจะทำถั่วเน่าเมอะกินเสมอ (เมอะ = เข้ม)', `category_vocab_id`='CV0017';
