INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03472', 'ᨵᨶᩪ', '[ทะ-นู]', 'ธนู', 'น. ธนู รูปวัวหรือควายที่ใช้ตอกสานหรือใช้ดินปั้น แล้วลงอาคมเพื่อใช้ต่อต้านศัตรู', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᨶᩪ', `reading`='[ทะ-นู]', `meaning`='น. ธนู รูปวัวหรือควายที่ใช้ตอกสานหรือใช้ดินปั้น แล้วลงอาคมเพื่อใช้ต่อต้านศัตรู', `category_vocab_id`='CV0017';
