INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03495', 'ᨵᩢᨾ᩠ᨾᩡ', '[ทำ-มะ]', 'ธัมมะ', 'น. คุณความดี คำสั่งสอนในศาสนา หลักประพฤติปฏิบัติในศาสนา ความจริง ความถูกต้อง กฎเกณฑ์ กฎหมาย', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩢᨾ᩠ᨾᩡ', `reading`='[ทำ-มะ]', `meaning`='น. คุณความดี คำสั่งสอนในศาสนา หลักประพฤติปฏิบัติในศาสนา ความจริง ความถูกต้อง กฎเกณฑ์ กฎหมาย', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03496', 'ᨵᩢᨾ᩠ᨾᩥᨠᨠᩣᨩ', '[ทำ-มิ-กะ-ลาด]', 'ธัมมิกกาช', 'น. ราชาผู้ทรงธรรม', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩢᨾ᩠ᨾᩥᨠᨠᩣᨩ', `reading`='[ทำ-มิ-กะ-ลาด]', `meaning`='น. ราชาผู้ทรงธรรม', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03497', 'ᨵᩢᨾ᩠ᨾ', '[ทำ]', 'ธัมม์', 'น. คัมภีร์ ใบลานที่เกี่ยวข้องกับพุทธศาสนา โดยทั่วไปเรียกว่า ธัมม์; คำสั่งสอนในพุทธศาสนา; ว. ดีงาม ถูกต้อง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩢᨾ᩠ᨾ', `reading`='[ทำ]', `meaning`='น. คัมภีร์ ใบลานที่เกี่ยวข้องกับพุทธศาสนา โดยทั่วไปเรียกว่า ธัมม์; คำสั่งสอนในพุทธศาสนา; ว. ดีงาม ถูกต้อง', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03498', 'ᨵᩢᨾ᩠ᨾᨩᩣᨲᩣᨷᩦᨠᩮᩥ᩠ᨯ', '[ทำ-จา-ต๋า-ปี-เกิด]', 'ธัมม์ชาตาปีเกิด', 'น. คัมภีร์ที่กำหนดให้ผู้เกิดในแต่ละปีนักษัตรพึงสร้างหรือมีส่วนสร้างถวายไว้ในพุทธศาสนา ซึ่งมีชื่อคัมภีร์หรือชาดกดังนี้ ปีไจ้ (ชวด)-เตมีย์ชาดก; ปีเป้า (ฉลู)-มหาเวสสันดรชาดก; ปียี (ขาล)-สุทธนูชาดก; ปีเหม้า (เถาะ)-เนมิราชชาดก; ปีสี (มะโรง)-สมภูมิตต์ชาดก; ปีไส้ (มะเส็ง)-ภูริทัตต์ชาดก; ปีสะง้า (มะเมีย)-สุธนชาดก; ปีเม็ด (มะแม)-ฉัททันต์ชาดก; ปีสัน (วอก)-มโหสถ; ปีเล้า (ระกา)-สิทธาตถ์หรืออกบวช; ปีเส็ด (จอ)-กุสสราชชาดก; ปีไค้ (กุน)-สุตตโสมชาดก (บุญคิด)', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩢᨾ᩠ᨾᨩᩣᨲᩣᨷᩦᨠᩮᩥ᩠ᨯ', `reading`='[ทำ-จา-ต๋า-ปี-เกิด]', `meaning`='น. คัมภีร์ที่กำหนดให้ผู้เกิดในแต่ละปีนักษัตรพึงสร้างหรือมีส่วนสร้างถวายไว้ในพุทธศาสนา ซึ่งมีชื่อคัมภีร์หรือชาดกดังนี้ ปีไจ้ (ชวด)-เตมีย์ชาดก; ปีเป้า (ฉลู)-มหาเวสสันดรชาดก; ปียี (ขาล)-สุทธนูชาดก; ปีเหม้า (เถาะ)-เนมิราชชาดก; ปีสี (มะโรง)-สมภูมิตต์ชาดก; ปีไส้ (มะเส็ง)-ภูริทัตต์ชาดก; ปีสะง้า (มะเมีย)-สุธนชาดก; ปีเม็ด (มะแม)-ฉัททันต์ชาดก; ปีสัน (วอก)-มโหสถ; ปีเล้า (ระกา)-สิทธาตถ์หรืออกบวช; ปีเส็ด (จอ)-กุสสราชชาดก; ปีไค้ (กุน)-สุตตโสมชาดก (บุญคิด)', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03499', 'ᨵᩢᨾ᩠ᨾᨩᩣᨲᩣᩅᩢ᩠ᨶᨠᩮᩥ᩠ᨯ', '[ทำ-จา-ต๋า-วัน-เกิด]', 'ธัมม์ชาตาวันเกิด', 'น. คัมภีร์ที่กำหนดให้ผู้เกิดในแต่ละวันพึงสร้างหรือมีส่วนสร้างถวายไว้ในพุทธศาสนา ซึ่งมีชื่อคัมภีร์หรือชาดกดังนี้ วันอาทิตย์-สังขิณี; วันจันทร์-ภิงคะ; วันอังคาร-ธาตุกถา; วันพุธ-บุคคลปัญญัติ; วันพฤหัสบดี-กถาวัตถุ; วันศุกร์-ยมกะ; วันเสาร์-มหาปัฏฐานสูตร (บุญคิด)', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩢᨾ᩠ᨾᨩᩣᨲᩣᩅᩢ᩠ᨶᨠᩮᩥ᩠ᨯ', `reading`='[ทำ-จา-ต๋า-วัน-เกิด]', `meaning`='น. คัมภีร์ที่กำหนดให้ผู้เกิดในแต่ละวันพึงสร้างหรือมีส่วนสร้างถวายไว้ในพุทธศาสนา ซึ่งมีชื่อคัมภีร์หรือชาดกดังนี้ วันอาทิตย์-สังขิณี; วันจันทร์-ภิงคะ; วันอังคาร-ธาตุกถา; วันพุธ-บุคคลปัญญัติ; วันพฤหัสบดี-กถาวัตถุ; วันศุกร์-ยมกะ; วันเสาร์-มหาปัฏฐานสูตร (บุญคิด)', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03500', 'ᨵᩢᨾ᩠ᨾᨩᩣᨲᩣᩮᨯᩥᩋ᩠ᨶᨠᩮᩥ᩠ᨯ', '[ทำ-จา-ต๋า-เดือน-เกิด]', 'ธัมม์ชาตาเดือนเกิด', 'น. คัมภีร์ที่กำหนดให้ผู้เกิดในแต่ละเดือนพึงสร้างหรือมีส่วนสร้างถวายไว้ในพุทธศาสนา ซึ่งมีชื่อคัมภีร์หรือชาดกดังนี้ เดือนยี่-ช้างฉัททันต์ หรือปทุมกุมาร; เดือนสาม-มัฏฐกุณฑลี หรือมโหสถ; เดือนสี่-หงส์ผาคำ หรือภูริทัตต์; เดือนห้า-อุทรา หรือปโรสาท; เดือนหก-พุทธโฆสา; เดือนเจ็ด-อรินทุมหรือแม่ราช; เดือนแปด-ภารทานพหรือสิทธาตถ์; เดือนเก้า-พุทธาภิเษก หรือสิบชาติ; เดือนสิบ-สุวรรณสาม; เดือนสิบเอ็ด-พุทธนิพพาน หรือเวสสันตระ; เดือนสิบสอง-มหามังคละสูตรหรือสมภมิตต์ (บุญคิด)', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩢᨾ᩠ᨾᨩᩣᨲᩣᩮᨯᩥᩋ᩠ᨶᨠᩮᩥ᩠ᨯ', `reading`='[ทำ-จา-ต๋า-เดือน-เกิด]', `meaning`='น. คัมภีร์ที่กำหนดให้ผู้เกิดในแต่ละเดือนพึงสร้างหรือมีส่วนสร้างถวายไว้ในพุทธศาสนา ซึ่งมีชื่อคัมภีร์หรือชาดกดังนี้ เดือนยี่-ช้างฉัททันต์ หรือปทุมกุมาร; เดือนสาม-มัฏฐกุณฑลี หรือมโหสถ; เดือนสี่-หงส์ผาคำ หรือภูริทัตต์; เดือนห้า-อุทรา หรือปโรสาท; เดือนหก-พุทธโฆสา; เดือนเจ็ด-อรินทุมหรือแม่ราช; เดือนแปด-ภารทานพหรือสิทธาตถ์; เดือนเก้า-พุทธาภิเษก หรือสิบชาติ; เดือนสิบ-สุวรรณสาม; เดือนสิบเอ็ด-พุทธนิพพาน หรือเวสสันตระ; เดือนสิบสอง-มหามังคละสูตรหรือสมภมิตต์ (บุญคิด)', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03501', 'ᨵᩣᨲᩩ', '[ทาด]', 'ธาตุ', 'น. กระดูกของพระพุทธเจ้า พระปัจเจกพุทธเจ้าและพระอรหันต์ โดยทั่วไปเรียกรวมกันว่าพระธาตุ; สถูป เจดีย์; สิ่งที่ถือกันว่าเป็นส่วนสำคัญ ที่คุมกันเป็นร่างของสิ่งทั้งหลาย โดยทั่วไปเชื่อว่ามี 4 ธาตุ คือ ดิน น้ำ ไฟ ลม', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨵᩣᨲᩩ', `reading`='[ทาด]', `meaning`='น. กระดูกของพระพุทธเจ้า พระปัจเจกพุทธเจ้าและพระอรหันต์ โดยทั่วไปเรียกรวมกันว่าพระธาตุ; สถูป เจดีย์; สิ่งที่ถือกันว่าเป็นส่วนสำคัญ ที่คุมกันเป็นร่างของสิ่งทั้งหลาย โดยทั่วไปเชื่อว่ามี 4 ธาตุ คือ ดิน น้ำ ไฟ ลม', `category_vocab_id`='CV0017';
