INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03893', 'ᨷ᩠ᩋᨠᨪᩴ᩠ᩋ', '[บอก-ซอ]', 'บอกซอ', 'น. หีบเสียง เครื่องทำให้จานเสียงหมุนและขับเสียงออกมา ในยุคแรกมักเป็นแผ่นเสียงเพลงซอ จึงเรียกบอกซอ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩋᨠᨪᩴ᩠ᩋ', `reading`='[บอก-ซอ]', `meaning`='น. หีบเสียง เครื่องทำให้จานเสียงหมุนและขับเสียงออกมา ในยุคแรกมักเป็นแผ่นเสียงเพลงซอ จึงเรียกบอกซอ', `category_vocab_id`='CV0017';
