INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03896', 'ᨷ᩠ᩋᨠᨳᩫ᩠ᨸ', '[บอก-ถบ]', 'บอกถบ', 'น. ของเล่นเด็กประกอบด้วยกระบอกไม้ไผ่ขนาดเล็ก มีแกนไม้ เมื่อกระทุ้งแกนจะส่งกระสุนด้วยแรงอัดอากาศและมีเสียงระเบิดดัง; ถบ บอกถอบ กล้องถบ กล้องถอบ ก็ว่า', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩋᨠᨳᩫ᩠ᨸ', `reading`='[บอก-ถบ]', `meaning`='น. ของเล่นเด็กประกอบด้วยกระบอกไม้ไผ่ขนาดเล็ก มีแกนไม้ เมื่อกระทุ้งแกนจะส่งกระสุนด้วยแรงอัดอากาศและมีเสียงระเบิดดัง; ถบ บอกถอบ กล้องถบ กล้องถอบ ก็ว่า', `category_vocab_id`='CV0017';
