INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03901', 'ᨷ᩠ᩋᨠᩯᩅ᩠᩶ᨦ', '[บอก-แว้ง]', 'บอกแว้ง', 'น. เครื่องเล่นชนิดหนึ่ง ปรกติทำด้วยก้อนดินเหนียวมีไหว้ทำด้วยซังข้าวเป็นลูกสั้นยาวลดหลั่นกันเหมือนบอกไฟขึ้น ใช้ซังข้าวทำเป็นหางและทำเชือกเป็นบ่วงเพื่อเหวี่ยงขึ้นไปสูงให้ร่วงลงมาโดยมีเสียงไหว้ดังไพเราะ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩋᨠᩯᩅ᩠᩶ᨦ', `reading`='[บอก-แว้ง]', `meaning`='น. เครื่องเล่นชนิดหนึ่ง ปรกติทำด้วยก้อนดินเหนียวมีไหว้ทำด้วยซังข้าวเป็นลูกสั้นยาวลดหลั่นกันเหมือนบอกไฟขึ้น ใช้ซังข้าวทำเป็นหางและทำเชือกเป็นบ่วงเพื่อเหวี่ยงขึ้นไปสูงให้ร่วงลงมาโดยมีเสียงไหว้ดังไพเราะ', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03902', 'ᨷ᩠ᩋᨠᩱᨼ', '[บอก-ไฟ]', 'บอกไฟ', 'น. ดอกไม้ไฟหรือไฟพะเนียง ทำด้วยกระบอกไม้ไผ่หรือกระบอกดินเผาบรรจุดินจุด ใช้ตั้งหรือฝังให้ปลายกระบอกเสมอพื้นดินแล้วจุดไฟให้ลูกเป็นช่องาม; บอกไฟดอก ก็ว่า', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩋᨠᩱᨼ', `reading`='[บอก-ไฟ]', `meaning`='น. ดอกไม้ไฟหรือไฟพะเนียง ทำด้วยกระบอกไม้ไผ่หรือกระบอกดินเผาบรรจุดินจุด ใช้ตั้งหรือฝังให้ปลายกระบอกเสมอพื้นดินแล้วจุดไฟให้ลูกเป็นช่องาม; บอกไฟดอก ก็ว่า', `category_vocab_id`='CV0017';
