INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03937', 'ᨷ᩠ᨶᩢ', '[บัน]', 'บัน', 'น. เรียกวิธีการเทศนาจากคัมภีร์ใบลานโดยอ่านเฉพาะส่วนต้นและปลายของคัมภีร์นั้นว่า เทสนบัน; บรรพ์ ส่วน ตอน อย่างที่ใช้เรียกเลขสันดรชาดกกัณฑ์สักกบรรพ์ว่าสักกบัน ก. หยุด ทอดทิ้ง เว้นระยะ พัก ผัน เบน เช่น ตัดบัน คือ ตัดตอน ยืด เกาะ เหนี่ยว หยุด', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᨶᩢ', `reading`='[บัน]', `meaning`='น. เรียกวิธีการเทศนาจากคัมภีร์ใบลานโดยอ่านเฉพาะส่วนต้นและปลายของคัมภีร์นั้นว่า เทสนบัน; บรรพ์ ส่วน ตอน อย่างที่ใช้เรียกเลขสันดรชาดกกัณฑ์สักกบรรพ์ว่าสักกบัน ก. หยุด ทอดทิ้ง เว้นระยะ พัก ผัน เบน เช่น ตัดบัน คือ ตัดตอน ยืด เกาะ เหนี่ยว หยุด', `category_vocab_id`='CV0017';
