INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03939', 'ᨷᩫ᩠ᩅ', '[บัว]', 'บัว', 'น. ชื่อเรียกไม้น้ำ มีเหง้ายาวทอดอยู่ในตม ใบเป็นแผ่นกลมขอบเรียบ ก้านใบและก้านดอกแข็งมีหนาม ดอกชูขึ้นเหนือน้ำ; ถ้าใบเป็นแผ่นกลมเรียบหรือจักอยู่ชิดกันเป็นกระจุก ก้านใบและก้านดอกอ่อน ไม่มีหนาม ใบลอยอยู่บนผิวน้ำและดอกโผล่เหนือน้ำ ล้วนเรียก พ้าน หรือ ดอกพ้าน', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷᩫ᩠ᩅ', `reading`='[บัว]', `meaning`='น. ชื่อเรียกไม้น้ำ มีเหง้ายาวทอดอยู่ในตม ใบเป็นแผ่นกลมขอบเรียบ ก้านใบและก้านดอกแข็งมีหนาม ดอกชูขึ้นเหนือน้ำ; ถ้าใบเป็นแผ่นกลมเรียบหรือจักอยู่ชิดกันเป็นกระจุก ก้านใบและก้านดอกอ่อน ไม่มีหนาม ใบลอยอยู่บนผิวน้ำและดอกโผล่เหนือน้ำ ล้วนเรียก พ้าน หรือ ดอกพ้าน', `category_vocab_id`='CV0017';
