INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V03977', 'ᨷᩣ', '[บา]', 'บา', 'น. ชาย ชายหนุ่ม พี่ (สรรพนามบุรุษที่ 1 เอกพจน์) ครู อาจารย์ อาจารย์ในทางธรรม; นำหน้าชื่อบุคคลเพศชายบุรุษที่สองหรือที่สามแสดงว่าบุคคลนั้นมีสถานภาพต่ำกว่าผู้พูด; คำนำหน้าชื่อต้นไม้ ผลไม้ หรือวัตถุที่เป็นก้อน ทั้งนี้อาจใช้คำว่า บะ หมะ หมัก หมาก แทน บ่า ก็ได้ แต่พจนานุกรมนี้ใช้ บ่า; ว. คำลงท้ายเพื่อแสดงการบอกเล่าหรือชักชวนให้คล้อยตาม คล้าย วะ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷᩣ', `reading`='[บา]', `meaning`='น. ชาย ชายหนุ่ม พี่ (สรรพนามบุรุษที่ 1 เอกพจน์) ครู อาจารย์ อาจารย์ในทางธรรม; นำหน้าชื่อบุคคลเพศชายบุรุษที่สองหรือที่สามแสดงว่าบุคคลนั้นมีสถานภาพต่ำกว่าผู้พูด; คำนำหน้าชื่อต้นไม้ ผลไม้ หรือวัตถุที่เป็นก้อน ทั้งนี้อาจใช้คำว่า บะ หมะ หมัก หมาก แทน บ่า ก็ได้ แต่พจนานุกรมนี้ใช้ บ่า; ว. คำลงท้ายเพื่อแสดงการบอกเล่าหรือชักชวนให้คล้อยตาม คล้าย วะ', `category_vocab_id`='CV0017';
