INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04010', 'ᨷᩥ᩠ᨯ', '[บิ๊ด]; [บึด]', 'บิด', 'น. โรคบิด โรคลำไส้ใหญ่อักเสบ มีอาการปวดมวนและถ่ายอุจจาระเป็นมูกเลือด ปวดท้องอย่างรุนแรง ก. ปลิด ทำให้หลุดจากที่; หมุนให้เป็นเกลียวอย่างใช้ตอกมัดของ; ใช้นิ้วมือบีบเนื้ออย่างแรงแล้วหมุนอย่างบิดหู; ก. เจาะ สับ เฉพาะส่วนที่ต้องการ เช่น บิดหัวไม้สูง คือเจาะจมูกช้าง; ว. คำขยายจมูกว่า รูดังบิด คือจมูกบาน', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷᩥ᩠ᨯ', `reading`='[บิ๊ด]; [บึด]', `meaning`='น. โรคบิด โรคลำไส้ใหญ่อักเสบ มีอาการปวดมวนและถ่ายอุจจาระเป็นมูกเลือด ปวดท้องอย่างรุนแรง ก. ปลิด ทำให้หลุดจากที่; หมุนให้เป็นเกลียวอย่างใช้ตอกมัดของ; ใช้นิ้วมือบีบเนื้ออย่างแรงแล้วหมุนอย่างบิดหู; ก. เจาะ สับ เฉพาะส่วนที่ต้องการ เช่น บิดหัวไม้สูง คือเจาะจมูกช้าง; ว. คำขยายจมูกว่า รูดังบิด คือจมูกบาน', `category_vocab_id`='CV0017';
