INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04018', 'ᨷᩥ᩠᩶ᨦ', '[บิ้ง]', 'บิ้ง', 'ก. บั่น ลิ กะเทาะ ใช้กับของมีคม เช่น คมมีดที่กะเทาะจนเห็นรอยแหว่ง ถ้าบิ่นเพียงเล็กน้อยอย่างฟันบิ่นเรียก บิ้ง; น. ค้างคาวลูกหนู ค้างคาวขนาดเล็กขนสีขาวแกมดำ; น. ชื่อแมงมุมชนิดหนึ่งที่มีลำตัวยาวประมาณ 2 เซนติเมตร ตัวสีน้ำตาลอ่อน ขดรออยู่ ส่วนที่แบ่งออกมาจากส่วนใหญ่อย่างส่วนที่แบ่งจากใบพลู ถ้าเป็นส่วนขนาดใหญ่อย่างชิ้นที่แบ่งจากใบตองเพื่อห่อขนมเรียกว่า บ่าง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷᩥ᩠᩶ᨦ', `reading`='[บิ้ง]', `meaning`='ก. บั่น ลิ กะเทาะ ใช้กับของมีคม เช่น คมมีดที่กะเทาะจนเห็นรอยแหว่ง ถ้าบิ่นเพียงเล็กน้อยอย่างฟันบิ่นเรียก บิ้ง; น. ค้างคาวลูกหนู ค้างคาวขนาดเล็กขนสีขาวแกมดำ; น. ชื่อแมงมุมชนิดหนึ่งที่มีลำตัวยาวประมาณ 2 เซนติเมตร ตัวสีน้ำตาลอ่อน ขดรออยู่ ส่วนที่แบ่งออกมาจากส่วนใหญ่อย่างส่วนที่แบ่งจากใบพลู ถ้าเป็นส่วนขนาดใหญ่อย่างชิ้นที่แบ่งจากใบตองเพื่อห่อขนมเรียกว่า บ่าง', `category_vocab_id`='CV0017';
