INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04054', 'ᨷ᩵…ᨷ᩵…', '[บ่อ...บ่อ...]', 'บ่...บ่...', 'โครงสร้างสำนวนที่ต้องการย้ำความหนักแน่นหรือย้ำความรู้สึก โดยเติมคำกริยาที่มีความหมายคล้ายคลึงกันในส่วนที่กำหนด เช่น บ่กินบ่ใช้ คือไม่มีความต้องการ; บ่เอาบ่ชู คือไม่ยอมหรือไม่เห็นด้วย; บ่รู้บ่เห็น คือไม่รู้ไม่เห็น', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩵…ᨷ᩵…', `reading`='[บ่อ...บ่อ...]', `meaning`='โครงสร้างสำนวนที่ต้องการย้ำความหนักแน่นหรือย้ำความรู้สึก โดยเติมคำกริยาที่มีความหมายคล้ายคลึงกันในส่วนที่กำหนด เช่น บ่กินบ่ใช้ คือไม่มีความต้องการ; บ่เอาบ่ชู คือไม่ยอมหรือไม่เห็นด้วย; บ่รู้บ่เห็น คือไม่รู้ไม่เห็น', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04055', 'ᨷ᩵…ᩯᨴ᩶ᨷ᩵…ᩅ᩵ᩣ', '[บ่อ...แต๊บ่อ...ว่า]', 'บ่...แท้บ่...ว่า', 'โครงสร้างสำนวนที่เมื่อเติมคำวิเศษณ์ลงในที่ว่าง ใช้ขยายความหมายของคำวิเศษณ์นั้น ๆ เช่น บ่ดีแท้บ่ดีว่า คือเลวจริง ๆ อัปรีย์; บ่สุกแท้บ่สุกว่า คืออาหารหรือผลไม้ไม่สุกจริง ๆ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩵…ᩯᨴ᩶ᨷ᩵…ᩅ᩵ᩣ', `reading`='[บ่อ...แต๊บ่อ...ว่า]', `meaning`='โครงสร้างสำนวนที่เมื่อเติมคำวิเศษณ์ลงในที่ว่าง ใช้ขยายความหมายของคำวิเศษณ์นั้น ๆ เช่น บ่ดีแท้บ่ดีว่า คือเลวจริง ๆ อัปรีย์; บ่สุกแท้บ่สุกว่า คืออาหารหรือผลไม้ไม่สุกจริง ๆ', `category_vocab_id`='CV0017';
