INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04106', 'ᨷ᩵ᩉᩖᩢ᩠ᨦᨧᩡ', '[บ่อ-หลัง-จะ]', 'บ่หลังจะ', 'ว. คงจะ อาจจะ กระมัง ใช้ในการออกความคิดเห็นในเชิงแบ่งรับแบ่งสู้ เช่น ไอ้หน้อยบ่หลังจะไปแอ่วละคำ คือไอ้หนูอาจจะไปเที่ยวแล้วกระมัง; น่ากลัวจะ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩵ᩉᩖᩢ᩠ᨦᨧᩡ', `reading`='[บ่อ-หลัง-จะ]', `meaning`='ว. คงจะ อาจจะ กระมัง ใช้ในการออกความคิดเห็นในเชิงแบ่งรับแบ่งสู้ เช่น ไอ้หน้อยบ่หลังจะไปแอ่วละคำ คือไอ้หนูอาจจะไปเที่ยวแล้วกระมัง; น่ากลัวจะ', `category_vocab_id`='CV0017';
