INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04111', 'ᨷ᩵ᩬ', '[บ่อ]', 'บ่อ', 'น. ช่องลึกลงไปในดินหรือหิน ใช้เป็นที่ขังน้ำ หรือเป็นแหล่งกำเนิดของบางสิ่งบางอย่าง เช่น บ่อเกลือ บ่อแร่ เป็นต้น', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩵ᩬ', `reading`='[บ่อ]', `meaning`='น. ช่องลึกลงไปในดินหรือหิน ใช้เป็นที่ขังน้ำ หรือเป็นแหล่งกำเนิดของบางสิ่งบางอย่าง เช่น บ่อเกลือ บ่อแร่ เป็นต้น', `category_vocab_id`='CV0017';
