INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04231', 'ᨷᩫ᩠᩶ᨦᨣᩨ᩠ᨷ', '[บ้ง-คืบ]', 'บ้งคืบ', 'น. ตัวบ้งชนิดที่ตัวสีน้ำตาล มีลายเป็นทางหรือลายขวาง; บ้งคืบ ก็ว่า', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷᩫ᩠᩶ᨦᨣᩨ᩠ᨷ', `reading`='[บ้ง-คืบ]', `meaning`='น. ตัวบ้งชนิดที่ตัวสีน้ำตาล มีลายเป็นทางหรือลายขวาง; บ้งคืบ ก็ว่า', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04232', 'ᨷᩫ᩠᩶ᨦᩮᩃ᩠ᨶ', '[บ้ง-เลน]', 'บ้งเลน', 'น. ตัวบ้งชนิดที่ตัวสีน้ำตาล มีลายเป็นทางหรือลายขวาง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷᩫ᩠᩶ᨦᩮᩃ᩠ᨶ', `reading`='[บ้ง-เลน]', `meaning`='น. ตัวบ้งชนิดที่ตัวสีน้ำตาล มีลายเป็นทางหรือลายขวาง', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04233', 'ᨷ᩠ᩅ᩶ᨦ', '[บ้วง]', 'บ้วง', 'น. บ่วง ห่วง วง สิ่งที่ทำเป็นวงรูดสำหรับคล้อง เชือกที่ทำเป็นวงกลมขนาดค่อนข้างใหญ่สำหรับคล้องหรือจับสัตว์ใหญ่ ถ้าขนาดเล็กอย่างใช้ดักไก่เรียกว่า เบี้ยง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩅ᩶ᨦ', `reading`='[บ้วง]', `meaning`='น. บ่วง ห่วง วง สิ่งที่ทำเป็นวงรูดสำหรับคล้อง เชือกที่ทำเป็นวงกลมขนาดค่อนข้างใหญ่สำหรับคล้องหรือจับสัตว์ใหญ่ ถ้าขนาดเล็กอย่างใช้ดักไก่เรียกว่า เบี้ยง', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04234', 'ᨷ᩠ᩅ᩶ᨶ', '[บ้วน]', 'บ้วน', 'น. นาก ก. อาการที่ปลาโผล่ขึ้นมาฮุบเหยื่อเหนือผิวน้ำ; อาการน้ำไหลโผล่ขึ้นมาข้างบน เรียก น้ำบ้วน; บ้วน-ถ่ม ทำให้ของเหลวออกจากปาก เช่น บ้วนน้ำหมาก', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩅ᩶ᨶ', `reading`='[บ้วน]', `meaning`='น. นาก ก. อาการที่ปลาโผล่ขึ้นมาฮุบเหยื่อเหนือผิวน้ำ; อาการน้ำไหลโผล่ขึ้นมาข้างบน เรียก น้ำบ้วน; บ้วน-ถ่ม ทำให้ของเหลวออกจากปาก เช่น บ้วนน้ำหมาก', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04235', 'ᨷ᩠ᩅ᩶ᨾ', '[บ้วม]', 'บ้วม', 'ก. บุบ บู้ลง ยุบลง มักใช้กับภาชนะโลหะ เช่น บาตร ถ้ายุบมากเรียก บูบ ถ้ายุบมากจนแบนหรือเกือบแบน ใช้ แบบ แหบ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠ᩅ᩶ᨾ', `reading`='[บ้วม]', `meaning`='ก. บุบ บู้ลง ยุบลง มักใช้กับภาชนะโลหะ เช่น บาตร ถ้ายุบมากเรียก บูบ ถ้ายุบมากจนแบนหรือเกือบแบน ใช้ แบบ แหบ', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04236', 'ᨷ᩠᩶ᩋᨦ', '[บ้อง]', 'บ้อง', 'น. ปล้องไม้จำพวกไผ่ที่ขังข้อ; สิ่งที่ทำเป็นช่องคล้ายกระบอก เช่น ช่องสำหรับสวมด้ามสิ่วหรือด้ามเสียม', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠᩶ᩋᨦ', `reading`='[บ้อง]', `meaning`='น. ปล้องไม้จำพวกไผ่ที่ขังข้อ; สิ่งที่ทำเป็นช่องคล้ายกระบอก เช่น ช่องสำหรับสวมด้ามสิ่วหรือด้ามเสียม', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04237', 'ᨷ᩠᩶ᩋᨦᨧ᩠ᩋᨯ', '[บ้อง-จอด]', 'บ้องจอด', 'น. ช่องสำหรับสวมอย่างด้ามสิ่วหรือด้ามเสียมที่เกิดจากการม้วนปลายด้านหนึ่งของสิ่ว หรือเสียมเพื่อให้สอดด้าม; เสียมคันรีบ้องจอด', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠᩶ᩋᨦᨧ᩠ᩋᨯ', `reading`='[บ้อง-จอด]', `meaning`='น. ช่องสำหรับสวมอย่างด้ามสิ่วหรือด้ามเสียมที่เกิดจากการม้วนปลายด้านหนึ่งของสิ่ว หรือเสียมเพื่อให้สอดด้าม; เสียมคันรีบ้องจอด', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04238', 'ᨷ᩠᩶ᩋᩁ', '[บ้อน]', 'บ้อน', 'ก. ปลิ้น กลับข้างในบางส่วนให้โผล่ออกมา ทำให้สิ่งที่อยู่ภายในหลุดออกมาอย่างขุดเม็ดลำไยให้พ้นออกจากปาก', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠᩶ᩋᩁ', `reading`='[บ้อน]', `meaning`='ก. ปลิ้น กลับข้างในบางส่วนให้โผล่ออกมา ทำให้สิ่งที่อยู่ภายในหลุดออกมาอย่างขุดเม็ดลำไยให้พ้นออกจากปาก', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04239', 'ᨷ᩠᩶ᩋᩁᩯᨷ᩠᩶ᨶ', '[บ้อน-แป้น]', 'บ้อนแป้น', 'ก. อาการที่ใช้ลิ้นแยกเอาเมล็ดในผลไม้ออกจากเนื้อเพื่อกิน เช่น บ้อนแป้นเม็ดในลำไย น้อยหน่า', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩠᩶ᩋᩁᩯᨷ᩠᩶ᨶ', `reading`='[บ้อน-แป้น]', `meaning`='ก. อาการที่ใช้ลิ้นแยกเอาเมล็ดในผลไม้ออกจากเนื้อเพื่อกิน เช่น บ้อนแป้นเม็ดในลำไย น้อยหน่า', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04240', 'ᨷ᩶ᩣ', '[บ้า]', 'บ้า', 'ว. เสียสติ วิกลจริต ฟั่นเฟือน น. สะบ้า ชื่อไม้เถาชนิดหนึ่ง ฝักมีเมล็ดสีน้ำตาลไหม้กลมแบนแข็ง ใช้ทำยาและใช้ตอยในการเล่นบ้าบ้า หรือสะบ้า; ในเมืองหงส์หินและหงส์ผาดำเรียก หมากนิม นิม หรือนิมแดง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩶ᩣ', `reading`='[บ้า]', `meaning`='ว. เสียสติ วิกลจริต ฟั่นเฟือน น. สะบ้า ชื่อไม้เถาชนิดหนึ่ง ฝักมีเมล็ดสีน้ำตาลไหม้กลมแบนแข็ง ใช้ทำยาและใช้ตอยในการเล่นบ้าบ้า หรือสะบ้า; ในเมืองหงส์หินและหงส์ผาดำเรียก หมากนิม นิม หรือนิมแดง', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04241', 'ᨷ᩶ᩣ᩠ᨶ', '[บ้าน]', 'บ้าน', 'น. ที่อยู่ บริเวณที่เรือนตั้งอยู่ สิ่งปลูกสร้างสำหรับเป็นที่อยู่อาศัย หมู่บ้าน ถิ่นที่มนุษย์อยู่ ว. ที่อยู่ตามบ้าน เช่น หมู่บ้าน คู่บ้าน หมู่ป่า', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᨷ᩶ᩣ᩠ᨶ', `reading`='[บ้าน]', `meaning`='น. ที่อยู่ บริเวณที่เรือนตั้งอยู่ สิ่งปลูกสร้างสำหรับเป็นที่อยู่อาศัย หมู่บ้าน ถิ่นที่มนุษย์อยู่ ว. ที่อยู่ตามบ้าน เช่น หมู่บ้าน คู่บ้าน หมู่ป่า', `category_vocab_id`='CV0017';
