INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V04768', 'ᩮᨠᩢ᩠ᨷ', '[เก็บ]', 'เก็บ', 'ก. เก็บ, เอาไปหรือเอามาจากที่, เอาของที่หล่นอยู่ขึ้นมา สำนวน เก็บผักใส่ซ้า เก็บข้าใส่เมือง - หมายถึงรวบรวมผู้คนจากเมืองต่าง ๆ มาไว้ในเมืองเชียงใหม่', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩮᨠᩢ᩠ᨷ', `reading`='[เก็บ]', `meaning`='ก. เก็บ, เอาไปหรือเอามาจากที่, เอาของที่หล่นอยู่ขึ้นมา สำนวน เก็บผักใส่ซ้า เก็บข้าใส่เมือง - หมายถึงรวบรวมผู้คนจากเมืองต่าง ๆ มาไว้ในเมืองเชียงใหม่', `category_vocab_id`='CV0017';
