INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05463', 'ᩯᨠ᩠ᨦ᩠ᩁᩡᨠᨯ᩶ᩣ᩠ᨦ', 'แก๋งกะด้าง', 'แกงกระด้าง', 'น.แกงที่ได้จากการต้มเนื้อหมู เครื่องในหมู หูหมู ให้เปื่อย ทิ้งไว้ในที่เย็นเช่นในตู้เย็น หรืออากาศในหน้าหนาว เพื่อให้น้ำแกงเป็นวุ้น โรยด้วยใบผักชี; แก๋งเกิ้ม ก็ว่า', 'CV0002') ON DUPLICATE KEY UPDATE `lanna_word`='ᩯᨠ᩠ᨦ᩠ᩁᩡᨠᨯ᩶ᩣ᩠ᨦ', `reading`='แก๋งกะด้าง', `meaning`='น.แกงที่ได้จากการต้มเนื้อหมู เครื่องในหมู หูหมู ให้เปื่อย ทิ้งไว้ในที่เย็นเช่นในตู้เย็น หรืออากาศในหน้าหนาว เพื่อให้น้ำแกงเป็นวุ้น โรยด้วยใบผักชี; แก๋งเกิ้ม ก็ว่า', `category_vocab_id`='CV0002';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05464', 'ᩯᨠ᩠ᨦᨠᩡᨯ᩠᩶ᩣ᩠ᨦ', '[แก๋ง - กะ - ด้าง]', 'แกงกะด้าง', 'น. แกงที่ได้จากการต้มขาหมูให้เปื่อยแล้วทิ้งไว้ในที่เย็นเพื่อให้น้ำแกงเป็นวุ้น นิยมใช้พริกไทยและเกลือปรุงรส ปัจจุบันนิยมใช้ผงวุ้นช่วยให้กระด้าง', 'CV0002') ON DUPLICATE KEY UPDATE `lanna_word`='ᩯᨠ᩠ᨦᨠᩡᨯ᩠᩶ᩣ᩠ᨦ', `reading`='[แก๋ง - กะ - ด้าง]', `meaning`='น. แกงที่ได้จากการต้มขาหมูให้เปื่อยแล้วทิ้งไว้ในที่เย็นเพื่อให้น้ำแกงเป็นวุ้น นิยมใช้พริกไทยและเกลือปรุงรส ปัจจุบันนิยมใช้ผงวุ้นช่วยให้กระด้าง', `category_vocab_id`='CV0002';
