INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05468', 'ᩯᨠ᩠ᨦᩉᩢ᩠ᨦᩮᩃᩮᨩ᩠ᨿᨦᩯᩈ᩠ᨶ', '[แก๋ง - ฮัง - เล - เจียง - แสน]', 'แกงฮังเลเชียงแสน', 'น. แกงที่ใช้ผักเป็นหลัก ได้แก่ ถั่วฝักยาว, มะเขือยาว, หัวปลี, หน่อไม้ดอง, ขิง, หมูสามชั้น ใช้น้ำพริกแบบแกงส้ม เมื่อสุกเปื่อยดีแล้วคั่วงาดำใส่ลงไปด้วย', 'CV0002') ON DUPLICATE KEY UPDATE `lanna_word`='ᩯᨠ᩠ᨦᩉᩢ᩠ᨦᩮᩃᩮᨩ᩠ᨿᨦᩯᩈ᩠ᨶ', `reading`='[แก๋ง - ฮัง - เล - เจียง - แสน]', `meaning`='น. แกงที่ใช้ผักเป็นหลัก ได้แก่ ถั่วฝักยาว, มะเขือยาว, หัวปลี, หน่อไม้ดอง, ขิง, หมูสามชั้น ใช้น้ำพริกแบบแกงส้ม เมื่อสุกเปื่อยดีแล้วคั่วงาดำใส่ลงไปด้วย', `category_vocab_id`='CV0002';
