INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05751', 'ᩰᨠᩈᩢ᩠ᨾᨻᩦ', '[โก๋ - สำ - ปี]', 'โกสัมพี', 'น. เมืองโกสัมพี เมืองหลวงแคว้นวังสะ หมายถึงเมืองแสนหวีทางเหนือ รัฐฉาน ประเทศพม่า', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩰᨠᩈᩢ᩠ᨾᨻᩦ', `reading`='[โก๋ - สำ - ปี]', `meaning`='น. เมืองโกสัมพี เมืองหลวงแคว้นวังสะ หมายถึงเมืองแสนหวีทางเหนือ รัฐฉาน ประเทศพม่า', `category_vocab_id`='CV0017';
