INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05760', 'ᩰᨣᩫ᩠ᨠ', '[โก้ก]', 'โคก', 'น. สันหลัง ครีบ โดยปริยายใช้เรียกกระดูกสันหลังของคนหรือสัตว์ที่ผอมมาก; คูก ก็ว่า', 'CV0011') ON DUPLICATE KEY UPDATE `lanna_word`='ᩰᨣᩫ᩠ᨠ', `reading`='[โก้ก]', `meaning`='น. สันหลัง ครีบ โดยปริยายใช้เรียกกระดูกสันหลังของคนหรือสัตว์ที่ผอมมาก; คูก ก็ว่า', `category_vocab_id`='CV0011';
