INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05764', 'ᩰᨣᩫ᩠ᨾᨹ᩠ᨯᩢ', '[โกม - ผัด]', 'โคมผัด', 'น. โคมเวียน โคมซึ่งเขียนภาพบนที่ครอบ เมื่อจุดไฟแล้วครอบนั้นจะหมุน ทำให้เงาของภาพปรากฏบนผนังโคมโดยรอบ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩰᨣᩫ᩠ᨾᨹ᩠ᨯᩢ', `reading`='[โกม - ผัด]', `meaning`='น. โคมเวียน โคมซึ่งเขียนภาพบนที่ครอบ เมื่อจุดไฟแล้วครอบนั้นจะหมุน ทำให้เงาของภาพปรากฏบนผนังโคมโดยรอบ', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05765', 'ᩰᨣᩫ᩠ᨾᩁ᩠ᨦᩢᨾᩫ᩠ᨯᩈ᩶ᩫ᩠ᨾ', '[โกม - ฮัง - มด - ส้ม]', 'โคมรังมดส้ม', 'น. โคมที่ทำโครงไม้ไผ่เป็น ๘ เหลี่ยมขนาดกว้างประมาณ ๑ ฟุต ปิดด้วยกระดาษแก้วสลับสี มีช่องสำหรับจุดประทีปหรือเทียน นิยมประดับในเทศกาลยี่เป็ง คือ วันเพ็ญเดือนยี่', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩰᨣᩫ᩠ᨾᩁ᩠ᨦᩢᨾᩫ᩠ᨯᩈ᩶ᩫ᩠ᨾ', `reading`='[โกม - ฮัง - มด - ส้ม]', `meaning`='น. โคมที่ทำโครงไม้ไผ่เป็น ๘ เหลี่ยมขนาดกว้างประมาณ ๑ ฟุต ปิดด้วยกระดาษแก้วสลับสี มีช่องสำหรับจุดประทีปหรือเทียน นิยมประดับในเทศกาลยี่เป็ง คือ วันเพ็ญเดือนยี่', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05766', 'ᩰᨣᩫ᩠ᨾᩃ᩠ᩋ᩠ᨿ', '[โกม - ลอย]', 'โคมลอย', 'น. โคมกระดาษขนาดใหญ่ ใช้ควันไฟอัดเพื่อดันให้โคมลอยขึ้น นิยมทำมาปล่อยกันในเวลาสายในเทศกาลวันลอยกระทงและเทศน์มหาชาติ; ว่าวลม ก็เรียก', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩰᨣᩫ᩠ᨾᩃ᩠ᩋ᩠ᨿ', `reading`='[โกม - ลอย]', `meaning`='น. โคมกระดาษขนาดใหญ่ ใช้ควันไฟอัดเพื่อดันให้โคมลอยขึ้น นิยมทำมาปล่อยกันในเวลาสายในเทศกาลวันลอยกระทงและเทศน์มหาชาติ; ว่าวลม ก็เรียก', `category_vocab_id`='CV0017';
