INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05902', 'ᩱᨷ', '[ใบ]', 'ใบ', 'ก. นุ่ง ห่ม คลุม มักใช้คู่กับ บิง เป็น บิงใบ น. ส่วนของพืชที่ติดกับกิ่งหรือก้านโดยมากมีลักษณะแบน; สิ่งที่เป็นแผ่นหรือแบน เช่น ใบตรวจหวย - ใบตรวจผลการออกสลากกินแบ่ง', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷ', `reading`='[ใบ]', `meaning`='ก. นุ่ง ห่ม คลุม มักใช้คู่กับ บิง เป็น บิงใบ น. ส่วนของพืชที่ติดกับกิ่งหรือก้านโดยมากมีลักษณะแบน; สิ่งที่เป็นแผ่นหรือแบน เช่น ใบตรวจหวย - ใบตรวจผลการออกสลากกินแบ่ง', `category_vocab_id`='CV0017';
