INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05905', 'ᩱᨷᨷ᩠ᩋᨠ', '[ใบ-บอก]', 'ใบบอก', 'น. จดหมาย เช่น ใบบอกสีใหม่ (คนเชียงใหม่คนแรกที่ไปอเมริกา); หนังสือราชการ คำสั่ง ประกาศ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷᨷ᩠ᩋᨠ', `reading`='[ใบ-บอก]', `meaning`='น. จดหมาย เช่น ใบบอกสีใหม่ (คนเชียงใหม่คนแรกที่ไปอเมริกา); หนังสือราชการ คำสั่ง ประกาศ', `category_vocab_id`='CV0017';
