INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05907', 'ᩱᨷᩈᩦ', '[ใบ-สี]', 'ใบสี', 'น. บายศรี เครื่องเชิญขวัญหรือรับขวัญ ทำด้วยใบตองและมีเครื่องสังเวย', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷᩈᩦ', `reading`='[ใบ-สี]', `meaning`='น. บายศรี เครื่องเชิญขวัญหรือรับขวัญ ทำด้วยใบตองและมีเครื่องสังเวย', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05908', 'ᩱᨷᩋᨶᩩᨬᩣᨲ', '[ใบ-อะ-นุ-ญาด]', 'ใบอนุญาต', 'น. เอกสารที่ผู้มีอำนาจยินยอมให้ทำกิจได้ตามที่ยื่นขอ; ยืมจาก ใบอนุญาต', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷᩋᨶᩩᨬᩣᨲ', `reading`='[ใบ-อะ-นุ-ญาด]', `meaning`='น. เอกสารที่ผู้มีอำนาจยินยอมให้ทำกิจได้ตามที่ยื่นขอ; ยืมจาก ใบอนุญาต', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05909', 'ᩱᨷᩮᨦᩥ᩠ᨶ', '[ใบ-เงิน]', 'ใบเงิน', 'น. ต้นใบเงิน ชื่อพรรณไม้พุ่มต่างประเทศชนิดหนึ่ง พื้นใบเขียว กลางใบขาวช่อดอกสั้น ดอกสีม่วงแดง ถ้าชนิดที่พื้นใบเขียวกลางใบเหลืองเรียก ใบทอง และชนิดที่กิ่งและพื้นใบเป็นสีเขียวอมม่วงเรียกว่า ใบนาก (ยืมจาก ใบเงิน ใบทอง ใบนาก)', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷᩮᨦᩥ᩠ᨶ', `reading`='[ใบ-เงิน]', `meaning`='น. ต้นใบเงิน ชื่อพรรณไม้พุ่มต่างประเทศชนิดหนึ่ง พื้นใบเขียว กลางใบขาวช่อดอกสั้น ดอกสีม่วงแดง ถ้าชนิดที่พื้นใบเขียวกลางใบเหลืองเรียก ใบทอง และชนิดที่กิ่งและพื้นใบเป็นสีเขียวอมม่วงเรียกว่า ใบนาก (ยืมจาก ใบเงิน ใบทอง ใบนาก)', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05910', 'ᩱᨷᩱᨾ᩶', '[ใบ-ไม้]', 'ใบไม้', 'น. ใบของพืช (ดู ใบ) ชื่อพยาธิทางเดินอาหารในอันดับ Digenia มีหลายสกุลและหลายวงศ์ ลำตัวแบนคล้ายใบไม้ เป็นอันตรายต่อระบบทางเดินอาหารของคนและสัตว์ โดยเฉพาะตับ ถุงน้ำดี และท่อน้ำดี มีหลายชนิด (ยืมจาก พยาธิใบไม้)', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷᩱᨾ᩶', `reading`='[ใบ-ไม้]', `meaning`='น. ใบของพืช (ดู ใบ) ชื่อพยาธิทางเดินอาหารในอันดับ Digenia มีหลายสกุลและหลายวงศ์ ลำตัวแบนคล้ายใบไม้ เป็นอันตรายต่อระบบทางเดินอาหารของคนและสัตว์ โดยเฉพาะตับ ถุงน้ำดี และท่อน้ำดี มีหลายชนิด (ยืมจาก พยาธิใบไม้)', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05911', 'ᩱᨷᩱᩌ', '[ใบ-ไฮ]', 'ใบไฮ', 'น. ใบของต้นไทร ใบระกา ชื่อไม้หรือปูนทำเป็นลวดลายต่างๆ ติดกับตัวลายองค์ระหว่างช่อฟ้ากับหางหงส์', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩱᨷᩱᩌ', `reading`='[ใบ-ไฮ]', `meaning`='น. ใบของต้นไทร ใบระกา ชื่อไม้หรือปูนทำเป็นลวดลายต่างๆ ติดกับตัวลายองค์ระหว่างช่อฟ้ากับหางหงส์', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05912', 'ᩲᨷ᩶', '[ใบ้]', 'ใบ้', 'ว. ใบ้ พูดไม่ได้หรือไม่สามารถพูดเป็นถ้อยคำที่คนทั่วๆ ไปเข้าใจได้; มากอย่างยิ่ง เช่น นักใบ้นักง่าว - มากมายก่ายกอง น. หมาร่า เรียกแมงใบ้', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩲᨷ᩶', `reading`='[ใบ้]', `meaning`='ว. ใบ้ พูดไม่ได้หรือไม่สามารถพูดเป็นถ้อยคำที่คนทั่วๆ ไปเข้าใจได้; มากอย่างยิ่ง เช่น นักใบ้นักง่าว - มากมายก่ายกอง น. หมาร่า เรียกแมงใบ้', `category_vocab_id`='CV0017';
INSERT INTO `vocabulary` (`vocab_id`, `lanna_word`, `reading`, `thai_word`, `meaning`, `category_vocab_id`) VALUES ('V05913', 'ᩲᨷ᩶...ᨷ᩠ᩋᨯ', '[...ใบ้...บอด]', 'ใบ้...บอด', 'โครงสร้างวลีใช้ขยายความแสดงว่า จริงๆ มาก แท้ เช่น ดีใบ้ดีบอด - ดีจริงๆ; ...ใบ้...ง่าว ก็ว่า เช่น งามใบ้งามบอด - งามจริงๆ', 'CV0017') ON DUPLICATE KEY UPDATE `lanna_word`='ᩲᨷ᩶...ᨷ᩠ᩋᨯ', `reading`='[...ใบ้...บอด]', `meaning`='โครงสร้างวลีใช้ขยายความแสดงว่า จริงๆ มาก แท้ เช่น ดีใบ้ดีบอด - ดีจริงๆ; ...ใบ้...ง่าว ก็ว่า เช่น งามใบ้งามบอด - งามจริงๆ', `category_vocab_id`='CV0017';
